/**
 * Namespace `common`, Polski (pl), translated from the English source: words several areas use.
 *
 * Owner: phase 1 (the i18n core). Agents run one at a time, so any agent may
 * add a word that several areas need. Never rename, reword or remove a key:
 * other areas use it. (The pre-translation audit removed the stock words no
 * page used; i18n/key-usage.test.ts fails on a key nothing names.)
 */

import type { Translation } from '../../types';

export default {
  cancel: 'Anuluj',

  /* Counts. */
  'count.files': {
    one: '{count} plik',
    few: '{count} pliki',
    many: '{count} plików',
    other: '{count} pliku',
  },

  /* Lists: two names (or a list and one more name) joined by "and". listAnd() uses it. */
  'list.and': '{first} i {second}',
  /* Two names in the order they happen ("slot A, then recovery R"). listThen() uses it. */
  'list.then': '{first}, potem {second}',
  /* Two names in a plain list ("slot A, slot B"). listComma() uses it. */
  'list.comma': '{first}, {second}',
  /* Clauses in a list, where English uses a semicolon ("the flash backup; the patch step"). listSemicolon() uses it. */
  'list.semicolon': '{first}; {second}',

  /*
   * Firmware banks. A bank is one of the camera's three firmware slots, A, B and R; R is the recovery
   * slot, the last-resort copy the bootloader falls back to. {letter} is A, B or R: keep the Latin
   * letter. lib/bank-names.ts builds them (bankName, bankWords).
   * The name on its own (a table cell, a row label, the start of a line):
   */
  'bank.slot': 'Slot {letter}',
  'bank.slot:gen': 'slotu {letter}',
  'bank.slot:dat': 'slotowi {letter}',
  'bank.slot:acc': 'slot {letter}',
  'bank.slot:ins': 'slotem {letter}',
  'bank.slot:loc': 'slocie {letter}',
  'bank.recovery': 'Slot odzyskiwania {letter}',
  'bank.recovery:gen': 'slotu odzyskiwania {letter}',
  'bank.recovery:dat': 'slotowi odzyskiwania {letter}',
  'bank.recovery:acc': 'slot odzyskiwania {letter}',
  'bank.recovery:ins': 'slotem odzyskiwania {letter}',
  'bank.recovery:loc': 'slocie odzyskiwania {letter}',
  /* The same names inside a sentence (English writes them in lower case there). */
  'bank.slotInSentence': 'slot {letter}',
  'bank.slotInSentence:gen': 'slotu {letter}',
  'bank.slotInSentence:dat': 'slotowi {letter}',
  'bank.slotInSentence:acc': 'slot {letter}',
  'bank.slotInSentence:ins': 'slotem {letter}',
  'bank.slotInSentence:loc': 'slocie {letter}',
  'bank.recoveryInSentence': 'slot odzyskiwania {letter}',
  'bank.recoveryInSentence:gen': 'slotu odzyskiwania {letter}',
  'bank.recoveryInSentence:dat': 'slotowi odzyskiwania {letter}',
  'bank.recoveryInSentence:acc': 'slot odzyskiwania {letter}',
  'bank.recoveryInSentence:ins': 'slotem odzyskiwania {letter}',
  'bank.recoveryInSentence:loc': 'slocie odzyskiwania {letter}',
} satisfies Translation<'common'>;
